def push(repo: str | Path, remote: str = "origin", branch: str | None = None, set_upstream: bool = False) -> dict:
    _sync_path(repo)
    @writer_function
    def send():
        _check_name(remote)
        args = ["push"]
        if set_upstream:
            args.append("-u")
        args.append(remote)
        if branch:
            if branch.startswith("-"):
                raise GitError(f"잘못된 브랜치 이름: {branch!r}")
            args.append(branch)
        cp = run_git(repo, *args, check=False)
        return cp, cp.returncode, args
    cp, code, args = send()
    return {"ok": code == 0, "returncode": code, "stdout": cp.stdout, "stderr": cp.stderr,
            "command": "git " + " ".join(args)}

